-- El esquema como era ANTES de la tanda del 01/09: sin la tabla configuracion
-- (Ajustes no existia), sin rastro de quien vendio ni quien anulo, sin
-- precio_costo_anterior, y con fecha_hora todavia como DATE (el campo siempre
-- se llamo asi pero guardaba solo el dia).
--
-- No hay ninguna instalacion conocida en este estado, pero la migracion tiene
-- que poder levantarla igual: es el estado en el que quedo cualquier copia de
-- la base anterior al 01/09 (un respaldo viejo, la PC del negocio si se hubiera
-- instalado antes). Si la migracion solo supiera arreglar la base de Martin,
-- seria una curita, no una migracion.

create table categoria (id bigint generated by default as identity, descripcion varchar(255), nombre varchar(255), primary key (id));
create table compra (fecha_hora date, id bigint generated by default as identity, proveedor varchar(255), primary key (id));
create table detalle_compra (cantidad float(53) not null, precio_costo float(53) not null, subtotal float(53) not null, compra_id bigint, id bigint generated by default as identity, producto_id bigint, primary key (id));
create table detalle_venta (cantidad float(53) not null, precio_costo float(53) not null, precio_unitario float(53) not null, subtotal float(53) not null, id bigint generated by default as identity, producto_id bigint, venta_id bigint, primary key (id));
create table producto (activo boolean not null, fraccion_minima float(53), porcentaje_ganancia float(53) not null, precio_costo float(53) not null, precio_venta float(53) not null, stock float(53) not null, unidades_por_paquete integer, categoria_id bigint, id bigint generated by default as identity, version bigint, codigo_barras varchar(255), imagen_url varchar(255), nombre varchar(255), proveedor varchar(255), tipo_cantidad varchar(255), unidad_medida varchar(255), primary key (id));
create table promocion (activo boolean not null, cantidad_lleva integer not null, cantidad_paga integer not null, id bigint generated by default as identity, producto_id bigint, primary key (id));
create table usuario (id bigint generated by default as identity, nombre varchar(255), password varchar(255), rol varchar(255), username varchar(255) unique, primary key (id));
create table venta (total float(53) not null, fecha_hora date, id bigint generated by default as identity, primary key (id));

